# Final submission: Fill every component's entire bounding box
# This completes all rectangular structures

grid = np.array([list(map(int, line.split())) for line in grid_str.strip().split('\n')])

visited = np.zeros_like(grid, dtype=bool)
components = []

for r in range(grid.shape[0]):
    for c in range(grid.shape[1]):
        if grid[r, c] == 1 and not visited[r, c]:
            cells = set()
            stack = [(r, c)]
            while stack:
                cr, cc = stack.pop()
                if cr < 0 or cr >= grid.shape[0] or cc < 0 or cc >= grid.shape[1]:
                    continue
                if visited[cr, cc]:
                    continue
                if grid[cr, cc] != 1:
                    continue
                visited[cr, cc] = True
                cells.add((cr, cc))
                for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    stack.append((cr + dr, cc + dc))
            components.append(cells)

output_grid = np.copy(grid)

for comp in components:
    min_r = min(r for r, c in comp)
    max_r = max(r for r, c in comp)
    min_c = min(c for r, c in comp)
    max_c = max(c for r, c in comp)

    for r in range(min_r, max_r + 1):
        for c in range(min_c, max_c + 1):
            output_grid[r, c] = 1

output_json = {"action": "submit", "grid": output_grid.tolist()}

